
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_apbe_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_apbe", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-5.987699769569912e-02, -5.882876169946043e-02, -5.732717706049591e-02, -5.518028619025883e-02, -5.212012837088625e-02, -4.778187004600584e-02, -4.170090578351362e-02, -3.341152063434431e-02, -2.296825581570258e-02, -1.261077493688546e-02, -8.860523425076266e-03, -3.519717870897907e-02, -4.431143390821647e-02, -2.935355132750797e-02, -1.362137300234575e-02, -2.866362865481099e-03, -1.471420616700062e-04, -1.317246631796934e-06, -1.348740990407089e-09, -5.336994306277185e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


